import { Fox } from "./fox";

/** The fox's jump: speed and how long the button was held. */
export function jump(fox: Fox, held: number): number {
  const power = Math.min(held, 0.4) * 30;
  fox.vy = -power;
  return power;
}

export class Coin {
  constructor(public x: number, public y: number) {}
  collect(fox: Fox): boolean {
    return Math.abs(fox.x - this.x) < 16 && Math.abs(fox.y - this.y) < 16;
  }
}
